#ifndef DEBUG_MENU_H
#define DEBUG_MENU_H

#include <stdint.h>

/* -----------------------------------------------------------------------
 * debug_menu.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 28 Oct 2026 for Tony's display/UI subsystem.
 * BJT2 Sound Modulating Toy — Hidden Debug Screen Navigation
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * Pure logic behind the hidden debug screen, where the toy's diagnostics
 * and tests are: the five pages, how many cursor positions each page
 * has, where the encoder cursor goes next, what each Speaker and Faults
 * item does, the names drawn on screen, and the "hold BACK for 2 s on
 * Home" detector that opens the screen.
 *
 * Deliberately independent of ui_types.h: pages and items are plain
 * uint8_t values, so ui_state_machine.c and the firmware glue
 * (tony_debug.c) can both use this module without a circular include.
 * No HAL, no RTOS and no other subsystem's headers either — turning an
 * item into Tom's Tom_Test_t / TomTune_t or Brendon's SOC override
 * command is the glue's job.
 * ----------------------------------------------------------------------- */

/* ===================================================================
 * PAGES
 * The encoder walks System -> Storage -> Battery/power -> Speaker ->
 * Faults and wraps round. The first three are information pages (one
 * cursor position each, so every detent changes page); Speaker and
 * Faults are lists the cursor steps through item by item.
 * =================================================================== */
typedef enum {
    DEBUG_PAGE_SYSTEM = 0,  /* Build, uptime, heap, drop counters, stacks  */
    DEBUG_PAGE_STORAGE,     /* SD card, mount, bus width, capacity, MSC,
                             * the effect file being made (FX job)         */
    DEBUG_PAGE_POWER,       /* Gauge, charger, USB, alarms, SOC override   */
    DEBUG_PAGE_SPEAKER,     /* List: 10 test patterns + 3 tunes            */
    DEBUG_PAGE_FAULTS,      /* List: 5 fault injections                    */
    DEBUG_PAGE_COUNT        /* Sentinel — total number of pages            */
} debug_page_t;

#define DEBUG_NAME_MAX          16U     /* Longest page title / item name  */
#define DEBUG_INDEX_NONE        0xFFU   /* "Not a pattern / not a tune"    */

/* ===================================================================
 * SPEAKER PAGE ITEMS
 *   0..7    Sweep 100 Hz, 200 Hz, 500 Hz, 1 kHz, 2 kHz, 5 kHz, 8 kHz, 10 kHz
 *   8       Left only 1 kHz
 *   9       Right only 1 kHz
 *   10..12  Tune: startup, critical, fault beep
 * Pattern index 0..9 follows Tom's Tom_Test_t order from
 * TOM_TEST_SWEEP_100 to TOM_TEST_RIGHT_ONLY; tune index 0..2 mirrors
 * TomTune_t (TOM_TUNE_STARTUP, TOM_TUNE_CRITICAL, TOM_TUNE_FAULT).
 * =================================================================== */
#define DEBUG_SPEAKER_PATTERNS  10U     /* Items 0..9:   test patterns     */
#define DEBUG_SPEAKER_TUNES     3U      /* Items 10..12: tunes             */
#define DEBUG_SPEAKER_ITEMS     13U     /* Patterns + tunes                */

/* ===================================================================
 * FAULTS PAGE ITEMS
 *   0  Storage fault     simulated storage fault -> the fault screen
 *   1  Battery LOW 25%   SOC override 25 % for 300 s (low alarm)
 *   2  Battery CRIT 8%   SOC override  8 % for 300 s (critical, lockout)
 *   3  Battery OK 60%    SOC override 60 % for 65535 s, about 18 h
 *                        (everything clears; in practice until reboot)
 *   4  Clear overrides   SOC override with 0 s = back to the real SOC
 * The battery items only ask BrendonTask to pretend the gauge reads that
 * charge, so the real alarm, lockout, tune and status-bar code runs.
 * Battery OK asks for the longest override the message can carry, so one
 * push keeps the speaker on for a whole demo even if the gauge itself
 * reads below 10 % (a gauge that has not learned the pack can).
 * The values sit clearly inside Brendon's bands: low below 30 %,
 * critical below 10 %, everything released again at 32 %.
 * =================================================================== */
#define DEBUG_FAULT_ITEMS       5U
#define DEBUG_SOC_LOW_PCT       25U     /* Low alarm only (not critical)   */
#define DEBUG_SOC_CRIT_PCT      8U      /* Critical alarm + speaker lockout*/
#define DEBUG_SOC_OK_PCT        60U     /* Above every release point       */
#define DEBUG_SOC_OVERRIDE_S    300U    /* LOW / CRIT override: 5 minutes  */
#define DEBUG_SOC_OK_OVERRIDE_S 65535U  /* OK override: ~18 h (uint16 max) */

typedef enum {
    DEBUG_FAULT_ACT_NONE = 0,       /* Not a Faults item — do nothing      */
    DEBUG_FAULT_ACT_STORAGE,        /* Raise a simulated storage fault     */
    DEBUG_FAULT_ACT_SOC_OVERRIDE,   /* Ask BrendonTask to fake the SOC     */
    DEBUG_FAULT_ACT_CLEAR_OVERRIDE  /* Ask BrendonTask to drop the fake    */
} debug_fault_action_t;

/* ===================================================================
 * BACK-HOLD DETECTOR
 * Holding BACK for 2 s on Home opens the debug screen; nothing on Home
 * advertises it. A short press keeps its normal meaning (EVENT_GO_HOME
 * on the press edge), so the detector only watches the button level.
 * =================================================================== */
#define DEBUG_HOLD_MS           2000U   /* Hold time that opens the screen */

typedef struct {
    uint8_t  down;          /* 1 while BACK is held                        */
    uint8_t  fired;         /* 1 once this press is used up: it opened the
                             * screen, or an update saw it off Home        */
    uint32_t since_ms;      /* Tick of the press edge                      */
} debug_hold_t;

/**
 * debug_page_items
 * Number of cursor positions on a page: 1 on the information pages
 * (System, Storage, Battery/power), 13 on Speaker, 5 on Faults.
 *
 * @param page  A debug_page_t value.
 * @return      Item count, or 0 for an invalid page.
 */
uint8_t debug_page_items(uint8_t page);

/**
 * debug_cursor_next
 * One encoder detent clockwise. On a list page the cursor moves to the
 * next item; past the last item, and on every detent on an information
 * page, it moves to item 0 of the next page. After the last Faults item
 * it wraps round to System.
 *
 * An out-of-range position is first clamped to a valid one (a page past
 * the end becomes the last page, an item past the end of its page becomes
 * that page's last item) and then moved. NULL in either pointer: no change.
 *
 * @param page  In/out: current page (debug_page_t value).
 * @param item  In/out: current item on that page.
 */
void debug_cursor_next(uint8_t *page, uint8_t *item);

/**
 * debug_cursor_prev
 * One encoder detent counter-clockwise — the exact reverse of
 * debug_cursor_next. Before item 0 the cursor lands on the LAST item of
 * the previous page, so turning back walks a list bottom-up; from System
 * it wraps round to the last Faults item. Same clamping and NULL rules
 * as debug_cursor_next.
 *
 * @param page  In/out: current page (debug_page_t value).
 * @param item  In/out: current item on that page.
 */
void debug_cursor_prev(uint8_t *page, uint8_t *item);

/**
 * debug_speaker_is_tune
 * @param item  Speaker page item.
 * @return      1 for a tune (items 10..12), 0 for a test pattern or an
 *              out-of-range item.
 */
uint8_t debug_speaker_is_tune(uint8_t item);

/**
 * debug_speaker_pattern_index
 * Test-pattern index of a Speaker item: items 0..9 give 0..9, in Tom's
 * Tom_Test_t order (sweep 100 Hz .. 10 kHz, left only, right only).
 *
 * @param item  Speaker page item.
 * @return      0..9, or DEBUG_INDEX_NONE for a tune or an out-of-range item.
 */
uint8_t debug_speaker_pattern_index(uint8_t item);

/**
 * debug_speaker_tune_index
 * Tune index of a Speaker item: items 10, 11, 12 give 0 (startup),
 * 1 (critical), 2 (fault beep) — the TomTune_t numbering.
 *
 * @param item  Speaker page item.
 * @return      0..2, or DEBUG_INDEX_NONE for a pattern or an out-of-range item.
 */
uint8_t debug_speaker_tune_index(uint8_t item);

/**
 * debug_fault_item_action
 * What pushing a Faults item does, plus the SOC override the glue puts
 * into the BrendonCmd_t:
 *   item 0      DEBUG_FAULT_ACT_STORAGE         soc 0             seconds 0
 *   items 1..3  DEBUG_FAULT_ACT_SOC_OVERRIDE    soc 25 / 8 / 60   seconds 300 / 300 / 65535
 *   item 4      DEBUG_FAULT_ACT_CLEAR_OVERRIDE  soc 0             seconds 0
 *   other       DEBUG_FAULT_ACT_NONE            soc 0             seconds 0
 * Both outputs are always written when non-NULL; either may be NULL.
 *
 * @param item     Faults page item.
 * @param soc_pct  Out: override charge in percent. May be NULL.
 * @param seconds  Out: override duration, 0 = clear. May be NULL.
 * @return         The action for this item.
 */
debug_fault_action_t debug_fault_item_action(uint8_t item, uint8_t *soc_pct,
                                             uint16_t *seconds);

/**
 * debug_page_title
 * "System", "Storage", "Battery / power", "Speaker test", "Fault injection".
 *
 * @param page  A debug_page_t value.
 * @return      The title, or "?" for an invalid page. Never NULL.
 */
const char *debug_page_title(uint8_t page);

/**
 * debug_speaker_item_name
 * "Sweep 100 Hz" .. "Sweep 10 kHz", "Left only 1 kHz", "Right only 1 kHz",
 * "Tune: startup", "Tune: critical", "Tune: fault beep".
 *
 * @param item  Speaker page item.
 * @return      The name, or "?" out of range. Never NULL.
 */
const char *debug_speaker_item_name(uint8_t item);

/**
 * debug_fault_item_name
 * "Storage fault", "Battery LOW 25%", "Battery CRIT 8%", "Battery OK 60%",
 * "Clear overrides".
 *
 * @param item  Faults page item.
 * @return      The name, or "?" out of range. Never NULL.
 */
const char *debug_fault_item_name(uint8_t item);

/**
 * debug_hold_init
 * Resets the detector: button up, nothing fired. A zero-initialised
 * static debug_hold_t is the same thing. NULL is ignored.
 *
 * @param h  Detector state.
 */
void debug_hold_init(debug_hold_t *h);

/**
 * debug_hold_update
 * Feed the BACK level, and whether Home is shown, once per input scan.
 * Returns 1 exactly once per press: at the first update where BACK has
 * been held continuously for >= DEBUG_HOLD_MS AND on_home has been
 * non-zero on every update since the press edge.
 *
 * The whole 2 s must happen on Home. The first update that finds
 * on_home == 0 uses the press up until BACK is released, even if Home
 * comes back while it is still held. The glue works out on_home before it
 * handles the scan's events, so the BACK press that leaves the debug
 * screen, or that closes a fault screen shown over Home, is off Home at
 * its first update and can never (re)open the debug screen; a fault
 * screen opening part-way through a hold ends that hold the same way. A
 * press that starts on any other screen is used up too: its EVENT_GO_HOME
 * shows Home, but BACK has to be released and held again there.
 *
 * Any released sample resets the detector, so a second 2 s hold on Home
 * fires again. The raw level is fine: contact bounce only happens at the
 * edges and merely restarts the count a few ms later. The elapsed time
 * uses unsigned subtraction, so it is safe across the 32-bit tick
 * wrap-around.
 *
 * @param h        Detector state. NULL -> returns 0.
 * @param pressed  Non-zero while BACK is held.
 * @param on_home  Non-zero while the Home screen is shown.
 * @param now_ms   Millisecond tick, e.g. osKernelGetTickCount().
 * @return         1 = open the debug screen now, else 0.
 */
uint8_t debug_hold_update(debug_hold_t *h, uint8_t pressed, uint8_t on_home,
                          uint32_t now_ms);

#endif /* DEBUG_MENU_H */
